{
  "implementation": "import math

def solve(case):
    matrix = case['matrix']
    # Validate
    if not matrix or not isinstance(matrix, list):
        raise ValueError("Matrix must be a non-empty list")
    R = len(matrix)
    if R == 0:
        raise ValueError("Matrix has no rows")
    C = len(matrix[0])
    for row in matrix:
        if not isinstance(row, list) or len(row) != C:
            raise ValueError("Matrix must be rectangular")
        for val in row:
            if not isinstance(val, (int, float)):
            raise ValueError("Matrix values must be numbers")
    # Compute IDF
    idf = []
    for j in range(C):
        df = 0
        for i in range(R):
            if matrix[i][j] != 0:
                df += 1
        idf_val = math.log(1 + R / (1 + df))
        idf.append(round(idf_val, 6))
    # Compute weighted matrix and row degrees
    weighted_matrix = []
    row_degree = []
    for i in range(R):
        weighted_row = []
        sum_row = 0.0
        for j in range(C):
            w = matrix[i][j] * idf[j]
            weighted_row.append(round(w, 6))
            sum_row += w
        weighted_matrix.append(weighted_row)
        row_degree.append(round(sum_row, 6))
    return {
        "idf": idf,
        "weighted_matrix": weighted_matrix,
        "row_degree": row_degree
    }"
}
